            System.out.println(score + "점: 합격");
        } else if (score >= 90) {  // 90점 이상이면 우수예요.
            System.out.println(score + "점: 우수");
        } else {
            // 위 조건이 모두 거짓일 때만 와요.
            System.out.println(score + "점: 불합격");
        }
    }
}

